"use strict";(self.webpackChunkaklib_docs=self.webpackChunkaklib_docs||[]).push([["358"],{7897(t){t.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docs":[{"type":"link","href":"/AKLib/","label":"AKLib","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/AKLib/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/AKLib/getting-started/quickstart","label":"Quickstart","docId":"getting-started/quickstart","unlisted":false},{"type":"link","href":"/AKLib/getting-started/conventions","label":"Units & coordinates","docId":"getting-started/conventions","unlisted":false}],"collapsible":true},{"type":"category","label":"Configuration","items":[{"type":"link","href":"/AKLib/configuration/drivetrains","label":"Drivetrains","docId":"configuration/drivetrains","unlisted":false},{"type":"link","href":"/AKLib/configuration/sensors","label":"Sensors & odometry","docId":"configuration/sensors","unlisted":false},{"type":"link","href":"/AKLib/configuration/exit-conditions","label":"Exit conditions","docId":"configuration/exit-conditions","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Tutorials","items":[{"type":"link","href":"/AKLib/tutorials/first-auton","label":"Your first auton","docId":"tutorials/first-auton","unlisted":false},{"type":"link","href":"/AKLib/tutorials/motions","label":"Motions in depth","docId":"tutorials/motions","unlisted":false},{"type":"link","href":"/AKLib/tutorials/manual-pid-tuning","label":"Manual PID tuning","docId":"tutorials/manual-pid-tuning","unlisted":false},{"type":"link","href":"/AKLib/tutorials/auto-tuning","label":"Auto-tuning","docId":"tutorials/auto-tuning","unlisted":false},{"type":"link","href":"/AKLib/tutorials/imu-calibration","label":"IMU calibration","docId":"tutorials/imu-calibration","unlisted":false},{"type":"link","href":"/AKLib/tutorials/pure-pursuit","label":"Pure pursuit","docId":"tutorials/pure-pursuit","unlisted":false},{"type":"link","href":"/AKLib/tutorials/path-planner","label":"The AKLib Planner","docId":"tutorials/path-planner","unlisted":false},{"type":"link","href":"/AKLib/tutorials/motion-profiling","label":"Motion profiling & feedforward","docId":"tutorials/motion-profiling","unlisted":false},{"type":"link","href":"/AKLib/tutorials/auton-selector","label":"Auton selector","docId":"tutorials/auton-selector","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"API Reference","items":[{"type":"link","href":"/AKLib/api/chassis","label":"Chassis","docId":"api/chassis","unlisted":false},{"type":"link","href":"/AKLib/api/motion-params","label":"MotionParams","docId":"api/motion-params","unlisted":false},{"type":"link","href":"/AKLib/api/odometry","label":"Odometry & sensors","docId":"api/odometry","unlisted":false},{"type":"link","href":"/AKLib/api/drivetrain","label":"Drivetrain","docId":"api/drivetrain","unlisted":false},{"type":"link","href":"/AKLib/api/path","label":"Path","docId":"api/path","unlisted":false},{"type":"link","href":"/AKLib/api/autotune","label":"Auto-tuner","docId":"api/autotune","unlisted":false},{"type":"link","href":"/AKLib/api/control","label":"Control primitives","docId":"api/control","unlisted":false},{"type":"link","href":"/AKLib/api/units","label":"Units & pose types","docId":"api/units","unlisted":false},{"type":"link","href":"/AKLib/api/selector","label":"Selector","docId":"api/selector","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/AKLib/resources","label":"Resources & further reading","docId":"resources","unlisted":false}]},"docs":{"api/autotune":{"id":"api/autotune","title":"Auto-tuner","description":"Header Auto-tuning tutorial.","sidebar":"docs"},"api/chassis":{"id":"api/chassis","title":"Chassis","description":"The class your auton talks to. Owns the drivetrain, the odometry task, and every motion. Header: aklib/chassis.hpp (or just aklib/api.hpp).","sidebar":"docs"},"api/control":{"id":"api/control","title":"Control primitives","description":"The building blocks under every motion \u2014 and they\'re all public, so you can use them for your own mechanisms (lifts, flywheels, arms). Headers under aklib/control/.","sidebar":"docs"},"api/drivetrain":{"id":"api/drivetrain","title":"Drivetrain","description":"Header Configuration \u2192 Drivetrains.","sidebar":"docs"},"api/motion-params":{"id":"api/motion-params","title":"MotionParams","description":"The per-call knobs accepted by every motion. Use designated initializers and set only what you need:","sidebar":"docs"},"api/odometry":{"id":"api/odometry","title":"Odometry & sensors","description":"Headers Sensors & odometry.","sidebar":"docs"},"api/path":{"id":"api/path","title":"Path","description":"Header Pure pursuit tutorial. Most paths come from the Planner\'s code export.","sidebar":"docs"},"api/selector":{"id":"api/selector","title":"Selector","description":"Brain-screen autonomous selector. Header Auton selector tutorial.","sidebar":"docs"},"api/units":{"id":"api/units","title":"Units & pose types","description":"Headers Units & coordinates.","sidebar":"docs"},"configuration/drivetrains":{"id":"configuration/drivetrains","title":"Drivetrains","description":"AKLib supports two drivetrain families behind one interface, so every motion works on both. Motions output a ChassisSpeeds {vx, vy, omega}; the drivetrain mixes it to wheel voltages.","sidebar":"docs"},"configuration/exit-conditions":{"id":"configuration/exit-conditions","title":"Exit conditions","description":"Deciding when a motion is done matters as much as the motion itself. Every AKLib motion runs the same exit logic and returns the reason it ended.","sidebar":"docs"},"configuration/sensors":{"id":"configuration/sensors","title":"Sensors & odometry","description":"Odometry is the background task (10 ms) that tracks the robot\'s pose. OdomSensors is a menu: fill in what you have, AKLib picks the best strategy automatically.","sidebar":"docs"},"getting-started/conventions":{"id":"getting-started/conventions","title":"Units & coordinates","description":"The one rule","sidebar":"docs"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"Prerequisites","sidebar":"docs"},"getting-started/quickstart":{"id":"getting-started/quickstart","title":"Quickstart","description":"AKLib is configured by one file that reads like a form: robot_config.cpp. Every number you need to change is marked <-- FILL IN. This page walks each section.","sidebar":"docs"},"intro":{"id":"intro","title":"AKLib","description":"AKLib is a motion and tracking library for VEX V5, written in C++ on PROS 4. It combines the two things teams usually have to pick between:","sidebar":"docs"},"resources":{"id":"resources","title":"Resources & further reading","description":"AKLib\'s algorithms are standard, well-documented robotics techniques. If you want to understand (or extend) what\'s under the hood:","sidebar":"docs"},"tutorials/auto-tuning":{"id":"tutorials/auto-tuning","title":"Auto-tuning","description":"AKLib\'s auto-tuner finds your kD for a kP you choose, by bracketing the oscillation boundary and then golden-section searching it. The division of labor matters: kP sets how aggressive the motion is (a judgment call you make in two minutes), and kD \u2014 the tedious one to hand-tune \u2014 is found by measurement.","sidebar":"docs"},"tutorials/auton-selector":{"id":"tutorials/auton-selector","title":"Auton selector","description":"AKLib ships a brain-screen autonomous selector: EZ-Template\'s job with a robodash-style look \u2014 a header bar, tappable routine cards with color tags, the current pick highlighted, and the selection saved to the SD card so it survives power cycles. Colors follow the Affogato theme.","sidebar":"docs"},"tutorials/first-auton":{"id":"tutorials/first-auton","title":"Your first auton","description":"Prereqs: installed, config sheet filled, PIDs at least roughly tuned (auto-tuning makes that a button press).","sidebar":"docs"},"tutorials/imu-calibration":{"id":"tutorials/imu-calibration","title":"IMU calibration","description":"The IMU owns your heading, and heading accuracy is the single biggest lever on odometry quality: 1\xb0 of heading error becomes roughly 0.4\u2033 of position error per 24\u2033 driven. Ten minutes here pays for itself all season.","sidebar":"docs"},"tutorials/manual-pid-tuning":{"id":"tutorials/manual-pid-tuning","title":"Manual PID tuning","description":"Prefer the auto-tuner? Run it first \u2014 then use this page to understand and refine what it found. Manual tuning is still worth learning: it builds the intuition you need when something misbehaves at a competition.","sidebar":"docs"},"tutorials/motion-profiling":{"id":"tutorials/motion-profiling","title":"Motion profiling & feedforward","description":"Plain PID motions react to error. A motion profile plans the whole velocity curve before moving (accelerate \u2192 cruise \u2192 brake), and feedforward converts that plan directly into voltage \u2014 the PID only cleans up leftovers. The result: motions that take the same time, every time, with no overshoot drama.","sidebar":"docs"},"tutorials/motions":{"id":"tutorials/motions","title":"Motions in depth","description":"Every motion: takes a MotionParams struct of optional knobs, runs at 10 ms, respects exit conditions, and returns an ExitReason.","sidebar":"docs"},"tutorials/path-planner":{"id":"tutorials/path-planner","title":"The AKLib Planner","description":"\u25B6 Launch the Path Planner (also in the top navbar) \u2014 it opens in a new tab, runs entirely in your browser, and saves your work locally. Or open AKLib/planner/aklib-planner.html from the repo directly; both are the same tool.","sidebar":"docs"},"tutorials/pure-pursuit":{"id":"tutorials/pure-pursuit","title":"Pure pursuit","description":"Pure pursuit follows a pre-planned path by continuously chasing a lookahead point that slides along the path ahead of the robot. Because progress is measured by position, not time, getting bumped doesn\'t break anything \u2014 the robot just keeps following from wherever it ends up.","sidebar":"docs"}}}}')}}]);